START TRANSACTION;

ALTER TABLE "Restaurants" ADD "IsActive" boolean NOT NULL DEFAULT TRUE;

ALTER TABLE "Restaurants" ADD "RestaurantApplicationId" integer;

CREATE TABLE "RestaurantApplications" (
    "RestaurantApplicationId" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "ApplicationReference" character varying(30) NOT NULL,
    "Status" character varying(30) NOT NULL,
    "TradingName" character varying(200),
    "RegisteredBusinessName" character varying(200),
    "CipcRegistrationNumber" character varying(100),
    "RestaurantCategory" text,
    "PhysicalAddress" text,
    "City" text,
    "RestaurantContactNumber" text,
    "BusinessEmail" text,
    "WebsiteOrSocialMediaUrl" text,
    "RepresentativeFullName" text,
    "RepresentativePosition" text,
    "RepresentativeMobileNumber" text,
    "RepresentativeEmail" text,
    "HasAuthorityToRepresent" boolean,
    "OffersCustomerCollection" boolean,
    "OffersRestaurantDelivery" boolean,
    "OffersGrubnBiteDelivery" boolean,
    "AveragePreparationTimeMinutes" integer,
    "MaximumDeliveryDistanceKm" numeric(8,2),
    "DeliveryInstructions" text,
    "CommissionOfferAccepted" boolean,
    "SubmittedAt" timestamp with time zone,
    "ReviewedByUserId" integer,
    "ReviewedAt" timestamp with time zone,
    "AdminComments" text,
    "RejectionReason" text,
    "DocumentsRequestedMessage" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_RestaurantApplications" PRIMARY KEY ("RestaurantApplicationId"),
    CONSTRAINT "FK_RestaurantApplications_Users_ReviewedByUserId" FOREIGN KEY ("ReviewedByUserId") REFERENCES "Users" ("UserId") ON DELETE SET NULL,
    CONSTRAINT "FK_RestaurantApplications_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("UserId") ON DELETE RESTRICT
);

CREATE TABLE "RestaurantCommissionSettings" (
    "RestaurantCommissionSettingId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantId" integer NOT NULL,
    "ActivationDate" timestamp with time zone NOT NULL,
    "PromotionStartDate" date NOT NULL,
    "PromotionEndDateExclusive" date NOT NULL,
    "PromotionCommissionRate" numeric(5,4) NOT NULL,
    "CollectionCommissionRate" numeric(5,4) NOT NULL,
    "RestaurantDeliveryCommissionRate" numeric(5,4) NOT NULL,
    "GrubnBiteDeliveryCommissionRate" numeric(5,4) NOT NULL,
    "IsPromotionActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_RestaurantCommissionSettings" PRIMARY KEY ("RestaurantCommissionSettingId"),
    CONSTRAINT "CK_RestaurantCommissionSettings_PromotionDates" CHECK ("PromotionEndDateExclusive" > "PromotionStartDate"),
    CONSTRAINT "CK_RestaurantCommissionSettings_Rates" CHECK ("PromotionCommissionRate" BETWEEN 0 AND 1 AND "CollectionCommissionRate" BETWEEN 0 AND 1 AND "RestaurantDeliveryCommissionRate" BETWEEN 0 AND 1 AND "GrubnBiteDeliveryCommissionRate" BETWEEN 0 AND 1),
    CONSTRAINT "FK_RestaurantCommissionSettings_Restaurants_RestaurantId" FOREIGN KEY ("RestaurantId") REFERENCES "Restaurants" ("RestaurantId") ON DELETE CASCADE
);

CREATE TABLE "RestaurantAgreementAcceptances" (
    "RestaurantAgreementAcceptanceId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantApplicationId" integer NOT NULL,
    "SignatoryFullName" text NOT NULL,
    "SignatoryPosition" text NOT NULL,
    "SignatoryEmail" text NOT NULL,
    "SignatoryMobileNumber" text NOT NULL,
    "ElectronicSignatureReference" text,
    "OtpVerifiedAt" timestamp with time zone NOT NULL,
    "AcceptedAt" timestamp with time zone NOT NULL,
    "IpAddress" text,
    "UserAgent" text,
    CONSTRAINT "PK_RestaurantAgreementAcceptances" PRIMARY KEY ("RestaurantAgreementAcceptanceId"),
    CONSTRAINT "FK_RestaurantAgreementAcceptances_RestaurantApplications_Resta~" FOREIGN KEY ("RestaurantApplicationId") REFERENCES "RestaurantApplications" ("RestaurantApplicationId") ON DELETE RESTRICT
);

CREATE TABLE "RestaurantApplicationHistories" (
    "RestaurantApplicationHistoryId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantApplicationId" integer NOT NULL,
    "PreviousStatus" character varying(30),
    "NewStatus" character varying(30),
    "Action" text NOT NULL,
    "Comment" text,
    "PerformedByUserId" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_RestaurantApplicationHistories" PRIMARY KEY ("RestaurantApplicationHistoryId"),
    CONSTRAINT "FK_RestaurantApplicationHistories_RestaurantApplications_Resta~" FOREIGN KEY ("RestaurantApplicationId") REFERENCES "RestaurantApplications" ("RestaurantApplicationId") ON DELETE RESTRICT,
    CONSTRAINT "FK_RestaurantApplicationHistories_Users_PerformedByUserId" FOREIGN KEY ("PerformedByUserId") REFERENCES "Users" ("UserId") ON DELETE SET NULL
);

CREATE TABLE "RestaurantApplicationReviewItems" (
    "RestaurantApplicationReviewItemId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantApplicationId" integer NOT NULL,
    "ReviewCategory" character varying(40) NOT NULL,
    "VerificationStatus" character varying(30) NOT NULL,
    "ReviewedByUserId" integer,
    "ReviewedAt" timestamp with time zone,
    "AdminComment" text,
    CONSTRAINT "PK_RestaurantApplicationReviewItems" PRIMARY KEY ("RestaurantApplicationReviewItemId"),
    CONSTRAINT "FK_RestaurantApplicationReviewItems_RestaurantApplications_Res~" FOREIGN KEY ("RestaurantApplicationId") REFERENCES "RestaurantApplications" ("RestaurantApplicationId") ON DELETE CASCADE,
    CONSTRAINT "FK_RestaurantApplicationReviewItems_Users_ReviewedByUserId" FOREIGN KEY ("ReviewedByUserId") REFERENCES "Users" ("UserId") ON DELETE SET NULL
);

CREATE TABLE "RestaurantBankingDetails" (
    "RestaurantBankingDetailId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantApplicationId" integer NOT NULL,
    "AccountHolderName" text NOT NULL,
    "BankName" text NOT NULL,
    "AccountType" text NOT NULL,
    "AccountNumberEncrypted" text NOT NULL,
    "BranchCode" text NOT NULL,
    "PayoutContactEmail" text NOT NULL,
    "VerificationStatus" character varying(30) NOT NULL,
    "VerifiedByUserId" integer,
    "VerifiedAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_RestaurantBankingDetails" PRIMARY KEY ("RestaurantBankingDetailId"),
    CONSTRAINT "FK_RestaurantBankingDetails_RestaurantApplications_RestaurantA~" FOREIGN KEY ("RestaurantApplicationId") REFERENCES "RestaurantApplications" ("RestaurantApplicationId") ON DELETE CASCADE,
    CONSTRAINT "FK_RestaurantBankingDetails_Users_VerifiedByUserId" FOREIGN KEY ("VerifiedByUserId") REFERENCES "Users" ("UserId") ON DELETE SET NULL
);

CREATE TABLE "RestaurantDocuments" (
    "RestaurantDocumentId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantApplicationId" integer NOT NULL,
    "DocumentType" character varying(40) NOT NULL,
    "DocumentDescription" text,
    "StoragePath" text NOT NULL,
    "OriginalFileName" character varying(255) NOT NULL,
    "ContentType" character varying(150) NOT NULL,
    "FileSize" bigint NOT NULL,
    "VerificationStatus" character varying(30) NOT NULL,
    "AdminComment" text,
    "VerifiedByUserId" integer,
    "UploadedAt" timestamp with time zone NOT NULL,
    "VerifiedAt" timestamp with time zone,
    CONSTRAINT "PK_RestaurantDocuments" PRIMARY KEY ("RestaurantDocumentId"),
    CONSTRAINT "FK_RestaurantDocuments_RestaurantApplications_RestaurantApplic~" FOREIGN KEY ("RestaurantApplicationId") REFERENCES "RestaurantApplications" ("RestaurantApplicationId") ON DELETE CASCADE,
    CONSTRAINT "FK_RestaurantDocuments_Users_VerifiedByUserId" FOREIGN KEY ("VerifiedByUserId") REFERENCES "Users" ("UserId") ON DELETE SET NULL
);

CREATE TABLE "RestaurantOperatingHours" (
    "RestaurantOperatingHourId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantApplicationId" integer NOT NULL,
    "DayOfWeek" character varying(15) NOT NULL,
    "IsOpen" boolean NOT NULL,
    "OpeningTime" time without time zone,
    "ClosingTime" time without time zone,
    CONSTRAINT "PK_RestaurantOperatingHours" PRIMARY KEY ("RestaurantOperatingHourId"),
    CONSTRAINT "FK_RestaurantOperatingHours_RestaurantApplications_RestaurantA~" FOREIGN KEY ("RestaurantApplicationId") REFERENCES "RestaurantApplications" ("RestaurantApplicationId") ON DELETE CASCADE
);

CREATE TABLE "RestaurantAgreementAcceptanceDocuments" (
    "AgreementAcceptanceDocumentId" integer GENERATED BY DEFAULT AS IDENTITY,
    "RestaurantAgreementAcceptanceId" integer NOT NULL,
    "PolicyDocumentId" integer,
    "DocumentTitle" text NOT NULL,
    "DocumentVersion" integer NOT NULL,
    "EffectiveDate" timestamp with time zone,
    "ContentHash" character varying(128) NOT NULL,
    "StoragePath" text,
    CONSTRAINT "PK_RestaurantAgreementAcceptanceDocuments" PRIMARY KEY ("AgreementAcceptanceDocumentId"),
    CONSTRAINT "FK_RestaurantAgreementAcceptanceDocuments_PolicyDocuments_Poli~" FOREIGN KEY ("PolicyDocumentId") REFERENCES "PolicyDocuments" ("PolicyDocumentId") ON DELETE RESTRICT,
    CONSTRAINT "FK_RestaurantAgreementAcceptanceDocuments_RestaurantAgreementA~" FOREIGN KEY ("RestaurantAgreementAcceptanceId") REFERENCES "RestaurantAgreementAcceptances" ("RestaurantAgreementAcceptanceId") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_Restaurants_RestaurantApplicationId" ON "Restaurants" ("RestaurantApplicationId") WHERE "RestaurantApplicationId" IS NOT NULL;

CREATE INDEX "IX_RestaurantAgreementAcceptanceDocuments_PolicyDocumentId" ON "RestaurantAgreementAcceptanceDocuments" ("PolicyDocumentId");

CREATE INDEX "IX_RestaurantAgreementAcceptanceDocuments_RestaurantAgreementA~" ON "RestaurantAgreementAcceptanceDocuments" ("RestaurantAgreementAcceptanceId");

CREATE INDEX "IX_RestaurantAgreementAcceptances_RestaurantApplicationId" ON "RestaurantAgreementAcceptances" ("RestaurantApplicationId");

CREATE INDEX "IX_RestaurantApplicationHistories_PerformedByUserId" ON "RestaurantApplicationHistories" ("PerformedByUserId");

CREATE INDEX "IX_RestaurantApplicationHistories_RestaurantApplicationId_Crea~" ON "RestaurantApplicationHistories" ("RestaurantApplicationId", "CreatedAt");

CREATE UNIQUE INDEX "IX_RestaurantApplicationReviewItems_RestaurantApplicationId_Re~" ON "RestaurantApplicationReviewItems" ("RestaurantApplicationId", "ReviewCategory");

CREATE INDEX "IX_RestaurantApplicationReviewItems_ReviewedByUserId" ON "RestaurantApplicationReviewItems" ("ReviewedByUserId");

CREATE UNIQUE INDEX "IX_RestaurantApplications_ApplicationReference" ON "RestaurantApplications" ("ApplicationReference");

CREATE INDEX "IX_RestaurantApplications_CreatedAt" ON "RestaurantApplications" ("CreatedAt");

CREATE INDEX "IX_RestaurantApplications_ReviewedByUserId" ON "RestaurantApplications" ("ReviewedByUserId");

CREATE INDEX "IX_RestaurantApplications_UserId_Status" ON "RestaurantApplications" ("UserId", "Status");

CREATE UNIQUE INDEX "IX_RestaurantBankingDetails_RestaurantApplicationId" ON "RestaurantBankingDetails" ("RestaurantApplicationId");

CREATE INDEX "IX_RestaurantBankingDetails_VerifiedByUserId" ON "RestaurantBankingDetails" ("VerifiedByUserId");

CREATE UNIQUE INDEX "IX_RestaurantCommissionSettings_RestaurantId" ON "RestaurantCommissionSettings" ("RestaurantId");

CREATE INDEX "IX_RestaurantDocuments_RestaurantApplicationId" ON "RestaurantDocuments" ("RestaurantApplicationId");

CREATE INDEX "IX_RestaurantDocuments_VerifiedByUserId" ON "RestaurantDocuments" ("VerifiedByUserId");

CREATE UNIQUE INDEX "IX_RestaurantOperatingHours_RestaurantApplicationId_DayOfWeek" ON "RestaurantOperatingHours" ("RestaurantApplicationId", "DayOfWeek");

ALTER TABLE "Restaurants" ADD CONSTRAINT "FK_Restaurants_RestaurantApplications_RestaurantApplicationId" FOREIGN KEY ("RestaurantApplicationId") REFERENCES "RestaurantApplications" ("RestaurantApplicationId") ON DELETE RESTRICT;

