START TRANSACTION;

ALTER TABLE "Users" ADD "EmailVerifiedAt" timestamp with time zone;

ALTER TABLE "Users" ADD "IsEmailVerified" boolean NOT NULL DEFAULT TRUE;

CREATE TABLE "EmailVerificationChallenges" (
    "EmailVerificationChallengeId" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "CodeHash" character varying(128) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastSentAt" timestamp with time zone NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "FailedAttempts" integer NOT NULL,
    "ResendCount" integer NOT NULL,
    "ResendWindowStartedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_EmailVerificationChallenges" PRIMARY KEY ("EmailVerificationChallengeId"),
    CONSTRAINT "FK_EmailVerificationChallenges_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("UserId") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_EmailVerificationChallenges_UserId" ON "EmailVerificationChallenges" ("UserId");

